import { type Capability } from "./Capability.js";
import { Policy } from "./Policy.js";

/**
 * The outcome of one access check.
 */
export type Decision = "allow" | "deny";

/**
 * The decision one policy reaches for one requested capability.
 */
export function decideAccess(policy: Policy, capability: Capability): Decision {
    return policy.consistent() && policy.effective().allows(capability) ? "allow" : "deny";
}

/**
 * The requested capability, when the policy actually hands it out.
 */
export function grantedCapability(policy: Policy, capability: Capability): Capability | undefined {
    return policy.effective().allows(capability) ? capability : undefined;
}
